+  attempt?: number;
+  reviewer?: string;
+};
+
+export type SliceOmission = {
+  path: string;
+  reason: string;
+  detail: string;
+  /** Bytes of diff text left out. 0 when the pre-filter dropped the file before it was rendered. */
+  bytes: number;
+};
